package com.hbm.machine.reactor.rbmk.fuel;
import com.hbm.hazard.HbmHazards;import net.minecraft.core.HolderLookup;import net.minecraft.util.Mth;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.Level;
/** Original RBMKFuelCraftingHandler, one occupied stack independent of count; hot or non-pellet rods cannot match. */
public final class RbmkFuelDisassembly extends CustomRecipe {
 public RbmkFuelDisassembly(CraftingBookCategory category){super(category);}private static ItemStack single(CraftingInput input){ItemStack found=ItemStack.EMPTY;for(int i=0;i<input.size();i++){var stack=input.getItem(i);if(stack.isEmpty())continue;if(!found.isEmpty())return ItemStack.EMPTY;found=stack;}return found;}
 @Override public boolean matches(CraftingInput input,Level level){var stack=single(input);return stack.getItem() instanceof RbmkFuelRodItem rod&&rod.pellet!=null&&RbmkFuelRodItem.getHullHeat(stack)<50&&RbmkFuelRodItem.getCoreHeat(stack)<50;}@Override public ItemStack assemble(CraftingInput input,HolderLookup.Provider lookup){return result(single(input));}public static ItemStack result(ItemStack stack){if(!(stack.getItem() instanceof RbmkFuelRodItem rod)||rod.pellet==null||RbmkFuelRodItem.getEnrichment(stack)>.99D||RbmkFuelRodItem.getHullHeat(stack)>=50||RbmkFuelRodItem.getCoreHeat(stack)>=50)return ItemStack.EMPTY;var result=new ItemStack(rod.pellet,8);int enrichment=4-Mth.clamp((int)Math.ceil(RbmkFuelRodItem.getEnrichment(stack)*5-1),0,4);result.set(HbmHazards.LEGACY_METADATA.get(),enrichment+(RbmkFuelRodItem.getPoisonLevel(stack)>=.5D?5:0));return result;}@Override public boolean canCraftInDimensions(int width,int height){return width*height>=1;}@Override public RecipeSerializer<?> getSerializer(){return RbmkFuelContent.DISASSEMBLY.get();}
}
